import{_ as i,o as t,c as a,a2 as o}from"./chunks/framework.DnrXFDHb.js";const u=JSON.parse('{"title":"MidiDeviceInput — MIDI 设备输入","description":"从实体 MIDI 设备读取 note_on/note_off 消息","frontmatter":{"title":"MidiDeviceInput — MIDI 设备输入","description":"从实体 MIDI 设备读取 note_on/note_off 消息"},"headers":[],"relativePath":"architecture/infrastructure/input/midi_device.md","filePath":"architecture/infrastructure/input/midi_device.md","lastUpdated":1773326634000}'),n={name:"architecture/infrastructure/input/midi_device.md"};function d(c,e,r,s,l,p){return t(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="midideviceinput-—-midi-设备输入" tabindex="-1">MidiDeviceInput — MIDI 设备输入 <a class="header-anchor" href="#midideviceinput-—-midi-设备输入" aria-label="Permalink to &quot;MidiDeviceInput — MIDI 设备输入&quot;">​</a></h1><p><strong>源文件</strong>：<code>src/streammuse/infrastructure/input/midi_device.py</code></p><p>从实体 MIDI 键盘或其他 MIDI 输入设备读取事件，是生产环境的默认输入方式。</p><hr><h2 id="midideviceinput" tabindex="-1"><code>MidiDeviceInput</code> <a class="header-anchor" href="#midideviceinput" aria-label="Permalink to &quot;`MidiDeviceInput`&quot;">​</a></h2><h3 id="init-device-name-str-none-none-none" tabindex="-1"><code>__init__(device_name: str | None = None) -&gt; None</code> <a class="header-anchor" href="#init-device-name-str-none-none-none" aria-label="Permalink to &quot;`__init__(device_name: str | None = None) -&gt; None`&quot;">​</a></h3><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>device_name</code></td><td><code>str | None</code></td><td>MIDI 设备名称；<code>None</code> 时 <code>mido</code> 自动选择系统中第一个可用设备</td></tr></tbody></table><hr><h3 id="read-events-iterator-musicalevent" tabindex="-1"><code>read_events() -&gt; Iterator[MusicalEvent]</code> <a class="header-anchor" href="#read-events-iterator-musicalevent" aria-label="Permalink to &quot;`read_events() -&gt; Iterator[MusicalEvent]`&quot;">​</a></h3><p>打开 MIDI 端口（首次调用时），轮询（<code>port.poll()</code>）消息。每条 <code>note_on</code>（velocity &gt; 0）或 <code>note_off</code>（含 velocity=0 的 note_on）消息都会 yield 一个 <code>MusicalEvent</code>。</p><p>所有发出的事件均为：</p><ul><li><code>tick=0</code>（Application 层负责赋值）</li><li><code>channel</code> 来源于 MIDI 消息</li><li><code>velocity=0</code> 对应 NOTE_OFF</li></ul><p>使用轮询（<code>poll</code>）而非阻塞（<code>receive</code>），以便 <code>close()</code> 能及时停止迭代器，无需等待下一条消息到来。</p><h3 id="close-none" tabindex="-1"><code>close() -&gt; None</code> <a class="header-anchor" href="#close-none" aria-label="Permalink to &quot;`close() -&gt; None`&quot;">​</a></h3><p>设置 <code>_running = False</code>，关闭 MIDI 端口。如果在 <code>read_events()</code> 阻塞时调用，迭代器在下次轮询时会检测到 <code>_running=False</code> 并退出。</p><hr><h2 id="设备名称查询" tabindex="-1">设备名称查询 <a class="header-anchor" href="#设备名称查询" aria-label="Permalink to &quot;设备名称查询&quot;">​</a></h2><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> mido</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(mido.get_input_names())   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 列出所有可用 MIDI 输入设备名称</span></span></code></pre></div><p>通过 CLI 的 <code>--midi-device-name</code> 参数指定设备名称。</p>',19)])])}const _=i(n,[["render",d]]);export{u as __pageData,_ as default};
